package com.procurement.invoice.entity;import jakarta.persistence.*;import lombok.*;import java.time.*;@Entity@Table(name="invoice_attachments")@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder public class InvoiceAttachment{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="invoice_id",nullable=false)private Invoice invoice;@Column(nullable=false)private String fileName;@Column(nullable=false,length=1000)private String filePath;@Column(nullable=false)private String fileType;@Column(nullable=false)private LocalDateTime uploadedAt;@PrePersist void pre(){if(uploadedAt==null)uploadedAt=LocalDateTime.now();}}
